static inline int var_get_u32(uint8_t *cp, const uint8_t *endp, uint32_t *i) {
    uint8_t *op = cp, c;
    uint32_t j = 0, s = 0;

    if (endp) {
        // Safe variant
        if (cp >= endp) {
            *i = 0;
            return 0;
        }

        do {
            c = *cp++;
            j |= (c & 0x7f) << s;
            s += 7;
        } while ((c & 0x80) && cp < endp);
    } else {
        // Unsafe variant
        do {
            c = *cp++;
            j |= (c & 0x7f) << s;
            s += 7;
        } while ((c & 0x80));
    }

    *i = j;
    return cp-op;
}
